<script setup lang="ts">
import {defineAsyncComponent,reactive} from 'vue'
import ConditionFilter from '@jetlinks-web-core/components/ConditionFilter'
import {quality} from '../api/quality'
import {useOrderPage} from '../hooks/useOrderPage'
import {orderStates,time} from '../shared/types'
const Detail=defineAsyncComponent(()=>import('../shared/components/QualityDetail.vue'))
const props=defineProps<{level:number}>(),vm=reactive(useOrderPage(props.level))
</script>
<template><a-card :title="(level===1?'公司':'项目')+'核查记录'"><template #extra><a-space><a-button :loading="vm.loading" @click="vm.load">刷新</a-button><a-button v-if="vm.can('quality-work-order','export')" @click="vm.exportRows">导出</a-button></a-space></template><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon />
 <a-space wrap style="margin-bottom:16px"><a-select v-model:value="vm.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" placeholder="全部业务项目" allow-clear style="width:240px" /><a-select v-model:value="vm.status" :options="Object.entries(orderStates).map(([value,label])=>({value:Number(value),label}))" placeholder="全部状态" allow-clear style="width:150px" /></a-space><ConditionFilter v-model="vm.terms" :fields="vm.fields" @change="vm.search" />
 <a-tabs v-model:activeKey="vm.mode"><a-tab-pane key="pool" tab="全部工单" /><a-tab-pane key="inspect" tab="待我核查" /><a-tab-pane key="rectify" tab="待我整改" /><a-tab-pane key="review" tab="待我复验" /><a-tab-pane key="completed" tab="我的已完成" /><a-tab-pane key="related" tab="历史参与" /></a-tabs>
 <a-table :data-source="vm.rows" :loading="vm.loading" row-key="id" :scroll="{x:'max-content'}" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}"><a-table-column title="任务名称" key="name"><template #default="{record}"><a-button type="link" @click="vm.detail(record)">{{record.taskName}}</a-button></template></a-table-column><a-table-column title="业务项目" data-index="projectName" /><a-table-column title="工单编号" data-index="taskCode" /><a-table-column title="状态" key="status"><template #default="{record}"><a-tag :color="record.workOrderStatus===4?'green':'blue'">{{orderStates[record.workOrderStatus]}}</a-tag></template></a-table-column><a-table-column title="生成时间" key="time"><template #default="{record}">{{time(record.scheduledTime)}}</template></a-table-column><a-table-column title="回传时限" key="deadline"><template #default="{record}">{{time(record.reportDeadline)}}</template></a-table-column><a-table-column title="总分" data-index="totalScore" /><a-table-column title="评价" data-index="evaluationName" /><a-table-column title="操作" key="actions"><template #default="{record}"><a-button type="link" @click="vm.detail(record)">查看 / 处理</a-button></template></a-table-column></a-table>
